package observability

import (
	"errors"
	"fmt"
)

// ErrorCode is the fixed enum every OmniCore Error reports.
type ErrorCode string

const (
	CodeAuthUnavailable     ErrorCode = "auth_unavailable"
	CodeServiceUnavailable  ErrorCode = "service_unavailable"
	CodeValidationFailed    ErrorCode = "validation_failed"
	CodeNotFound            ErrorCode = "not_found"
	CodeForbidden           ErrorCode = "forbidden"
	CodeConflict            ErrorCode = "conflict"
	CodeFailedPrecondition  ErrorCode = "failed_precondition"
	CodeInternal            ErrorCode = "internal"
	CodeIdempotencyConflict ErrorCode = "idempotency_conflict"
)

// Error is the canonical structured error envelope.
type Error struct {
	Code      ErrorCode
	Message   string
	RequestID string
	Cause     error
}

// New constructs an Error with no cause.
func New(code ErrorCode, message string) *Error {
	return &Error{Code: code, Message: message}
}

// Wrap constructs an Error from an existing error, preserving it as Cause.
func Wrap(code ErrorCode, message string, cause error) *Error {
	return &Error{Code: code, Message: message, Cause: cause}
}

// WithRequestID returns a copy of e with RequestID set.
func (e *Error) WithRequestID(reqID string) *Error {
	if e == nil {
		return nil
	}
	clone := *e
	clone.RequestID = reqID
	return &clone
}

func (e *Error) Error() string {
	if e == nil {
		return ""
	}
	if e.Cause != nil {
		return fmt.Sprintf("[%s] %s: %v", e.Code, e.Message, e.Cause)
	}
	return fmt.Sprintf("[%s] %s", e.Code, e.Message)
}

// Unwrap exposes the wrapped cause (so errors.Is/As work).
func (e *Error) Unwrap() error {
	if e == nil {
		return nil
	}
	return e.Cause
}

// IsCode returns true if err is a *Error whose Code equals code.
func IsCode(err error, code ErrorCode) bool {
	var e *Error
	if errors.As(err, &e) {
		return e.Code == code
	}
	return false
}


