package observability

import (
	"errors"
	"testing"
)

func TestNewAndError(t *testing.T) {
	e := New(CodeNotFound, "user not found")
	if e.Code != CodeNotFound {
		t.Errorf("Code = %s, want %s", e.Code, CodeNotFound)
	}
	if e.Error() != "[not_found] user not found" {
		t.Errorf("Error() = %q, want %q", e.Error(), "[not_found] user not found")
	}
}

func TestWrapPreservesCause(t *testing.T) {
	cause := errors.New("dial tcp: connection refused")
	e := Wrap(CodeServiceUnavailable, "identity-svc unreachable", cause)
	if !errors.Is(e, cause) {
		t.Error("errors.Is(e, cause) should be true")
	}
	if e.Unwrap() != cause {
		t.Error("Unwrap should return cause")
	}
}

func TestWithRequestID(t *testing.T) {
	e := New(CodeForbidden, "missing scope")
	if e.RequestID != "" {
		t.Error("default RequestID should be empty")
	}
	e2 := e.WithRequestID("req_abc")
	if e2.RequestID != "req_abc" {
		t.Errorf("e2.RequestID = %q, want req_abc", e2.RequestID)
	}
	if e.RequestID != "" {
		t.Error("WithRequestID should return a copy; original modified")
	}
}

func TestIsCode(t *testing.T) {
	e := New(CodeValidationFailed, "bad email")
	if !IsCode(e, CodeValidationFailed) {
		t.Error("IsCode should return true for matching code")
	}
	if IsCode(e, CodeNotFound) {
		t.Error("IsCode should return false for non-matching code")
	}
	if IsCode(errors.New("plain"), CodeValidationFailed) {
		t.Error("IsCode should return false for non-Error")
	}
}

func TestNilSafety(t *testing.T) {
	var e *Error
	if e.Error() != "" {
		t.Error("nil Error.Error() should return empty string")
	}
	if e.Unwrap() != nil {
		t.Error("nil Error.Unwrap() should return nil")
	}
	if e.WithRequestID("x") != nil {
		t.Error("nil Error.WithRequestID() should return nil")
	}
}


