package observability

import (
	"context"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	promhttp "github.com/prometheus/client_golang/prometheus/promhttp"
	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/metadata"
	"google.golang.org/grpc/status"
)

// ── Step 1.2: gRPC server metrics interceptors ────────────────────────────────

// setupMeterForTest creates a fresh meter and returns it + a cleanup func.
// Each test that needs a fresh registry must call this to avoid cross-test
// pollution from the package-level global.
func setupMeterForTest(t *testing.T, svcName string) (cleanup func()) {
	t.Helper()
	shutdown, err := SetupMeter(context.Background(), svcName, "1.0.0-test")
	if err != nil {
		t.Fatalf("SetupMeter: %v", err)
	}
	return func() {
		ctx, cancel := context.WithTimeout(context.Background(), time.Second)
		defer cancel()
		_ = shutdown(ctx)
	}
}

// statusClassFromGRPCCode tests exercise the internal mapping logic via the
// public interceptors. We verify the /metrics output contains expected labels.

func TestUnaryServerMetrics_RecordsDurationAndStatusClass_OK(t *testing.T) {
	cleanup := setupMeterForTest(t, "grpc-ok-test")
	defer cleanup()

	interceptor := UnaryServerMetricsInterceptor()

	called := false
	handler := func(ctx context.Context, req interface{}) (interface{}, error) {
		called = true
		return "resp", nil
	}

	info := &grpc.UnaryServerInfo{FullMethod: "/omnicore.identity.user.v1.UserService/InviteUser"}
	resp, err := interceptor(context.Background(), "req", info, handler)

	if !called {
		t.Error("handler was not called")
	}
	if err != nil {
		t.Errorf("expected nil error, got %v", err)
	}
	if resp != "resp" {
		t.Errorf("expected resp, got %v", resp)
	}

	body := scrapeMetrics(t)
	if !strings.Contains(body, `omnicore_requests_total`) {
		t.Errorf("expected omnicore_requests_total in /metrics; got:\n%s", body)
	}
	if !strings.Contains(body, `status_class="ok"`) {
		t.Errorf("expected status_class=ok in /metrics; got:\n%s", body)
	}
	if !strings.Contains(body, `omnicore_request_duration_seconds`) {
		t.Errorf("expected omnicore_request_duration_seconds in /metrics; got:\n%s", body)
	}
}

func TestUnaryServerMetrics_RecordsDurationAndStatusClass_ClientError(t *testing.T) {
	cleanup := setupMeterForTest(t, "grpc-client-err-test")
	defer cleanup()

	interceptor := UnaryServerMetricsInterceptor()

	// InvalidArgument → client_error per spec §hard requirements.
	handler := func(ctx context.Context, req interface{}) (interface{}, error) {
		return nil, status.Error(codes.InvalidArgument, "bad input")
	}
	info := &grpc.UnaryServerInfo{FullMethod: "/svc/Method"}
	_, err := interceptor(context.Background(), nil, info, handler)
	if err == nil {
		t.Fatal("expected error from handler")
	}

	body := scrapeMetrics(t)
	if !strings.Contains(body, `status_class="client_error"`) {
		t.Errorf("expected status_class=client_error; got:\n%s", body)
	}
}

func TestUnaryServerMetrics_RecordsDurationAndStatusClass_ServerError(t *testing.T) {
	cleanup := setupMeterForTest(t, "grpc-server-err-test")
	defer cleanup()

	interceptor := UnaryServerMetricsInterceptor()

	// Internal → server_error per spec §hard requirements.
	handler := func(ctx context.Context, req interface{}) (interface{}, error) {
		return nil, status.Error(codes.Internal, "something exploded")
	}
	info := &grpc.UnaryServerInfo{FullMethod: "/svc/Method"}
	_, _ = interceptor(context.Background(), nil, info, handler)

	body := scrapeMetrics(t)
	if !strings.Contains(body, `status_class="server_error"`) {
		t.Errorf("expected status_class=server_error; got:\n%s", body)
	}
}

// gRPC code bucketing table — covers every group in the spec mapping.
func TestGRPCStatusClassMapping(t *testing.T) {
	cases := []struct {
		code  codes.Code
		want  string
	}{
		{codes.OK, "ok"},
		// client_error group
		{codes.InvalidArgument, "client_error"},
		{codes.NotFound, "client_error"},
		{codes.PermissionDenied, "client_error"},
		{codes.Unauthenticated, "client_error"},
		{codes.AlreadyExists, "client_error"},
		{codes.FailedPrecondition, "client_error"},
		{codes.ResourceExhausted, "client_error"},
		{codes.OutOfRange, "client_error"},
		{codes.Canceled, "client_error"},
		// server_error group
		{codes.Internal, "server_error"},
		{codes.Unknown, "server_error"},
		{codes.Unavailable, "server_error"},
		{codes.DataLoss, "server_error"},
		{codes.Unimplemented, "server_error"},
		{codes.DeadlineExceeded, "server_error"},
		{codes.Aborted, "server_error"},
	}
	for _, tc := range cases {
		got := grpcStatusClass(tc.code)
		if got != tc.want {
			t.Errorf("grpcStatusClass(%v) = %q, want %q", tc.code, got, tc.want)
		}
	}
}

func TestUnaryServerMetrics_InFlightIncDecOnPanic(t *testing.T) {
	cleanup := setupMeterForTest(t, "grpc-panic-test")
	defer cleanup()

	interceptor := UnaryServerMetricsInterceptor()

	// A panicking handler must still decrement in-flight — the interceptor
	// must recover the panic, dec in-flight, then re-panic.
	panicHandler := func(ctx context.Context, req interface{}) (interface{}, error) {
		panic("test panic")
	}
	info := &grpc.UnaryServerInfo{FullMethod: "/svc/PanicMethod"}

	// The interceptor should re-panic so we catch it here.
	func() {
		defer func() {
			r := recover()
			if r == nil {
				t.Error("expected interceptor to re-panic after decrementing in-flight")
			}
		}()
		_, _ = interceptor(context.Background(), nil, info, panicHandler)
	}()

	// After the panic+recover, in-flight must be back to 0.
	// We verify this by scraping — the gauge should be 0 (or absent means 0).
	body := scrapeMetrics(t)
	// omnicore_requests_in_flight must be 0 — it was inc'd then dec'd.
	// Prometheus omits the line when the value is 0 for gauges that were
	// registered but returned to 0; we just need to confirm no crash.
	// A stricter check: if the line appears, it must not say "1".
	for _, line := range strings.Split(body, "\n") {
		if strings.HasPrefix(line, "omnicore_requests_in_flight") && !strings.HasPrefix(line, "#") {
			if strings.HasSuffix(strings.TrimSpace(line), " 1") {
				t.Errorf("in-flight gauge must be 0 after panic recovery; got: %q", line)
			}
		}
	}
}

func TestStreamServerMetrics_RecordsStatusClass(t *testing.T) {
	cleanup := setupMeterForTest(t, "grpc-stream-test")
	defer cleanup()

	interceptor := StreamServerMetricsInterceptor()

	// Use a minimal fake ServerStream.
	stream := &fakeServerStream{ctx: context.Background()}

	handler := func(srv interface{}, ss grpc.ServerStream) error {
		return nil // OK
	}
	info := &grpc.StreamServerInfo{FullMethod: "/svc/StreamMethod"}

	if err := interceptor(nil, stream, info, handler); err != nil {
		t.Errorf("unexpected error: %v", err)
	}

	body := scrapeMetrics(t)
	if !strings.Contains(body, `omnicore_requests_total`) {
		t.Errorf("expected omnicore_requests_total after stream; got:\n%s", body)
	}
}

func TestStreamServerMetrics_InFlightDecOnPanic(t *testing.T) {
	cleanup := setupMeterForTest(t, "grpc-stream-panic-test")
	defer cleanup()

	interceptor := StreamServerMetricsInterceptor()
	stream := &fakeServerStream{ctx: context.Background()}

	panicHandler := func(srv interface{}, ss grpc.ServerStream) error {
		panic("stream panic")
	}
	info := &grpc.StreamServerInfo{FullMethod: "/svc/StreamPanic"}

	func() {
		defer func() {
			r := recover()
			if r == nil {
				t.Error("expected interceptor to re-panic")
			}
		}()
		_ = interceptor(nil, stream, info, panicHandler)
	}()

	// Must not leave in-flight at 1.
	body := scrapeMetrics(t)
	for _, line := range strings.Split(body, "\n") {
		if strings.HasPrefix(line, "omnicore_requests_in_flight") && !strings.HasPrefix(line, "#") {
			if strings.HasSuffix(strings.TrimSpace(line), " 1") {
				t.Errorf("stream in-flight must be 0 after panic; got: %q", line)
			}
		}
	}
}

// ── Behavior: no-panic lazy init when SetupMeter was never called ─────────────

// TestInterceptorsDoNotPanicWithoutSetupMeter is the regression test for the
// CI-breaking bug where initSharedMetrics() panicked when globalReg == nil.
//
// Production always calls SetupMeter at boot. Tests that build the real gRPC
// server (e.g. mTLS + pact provider tests) do not call SetupMeter, which caused
// every such test to panic via UnaryServerMetricsInterceptor().
//
// The fix: lazy-init against a fallback Prometheus registry when globalReg is nil.
// This test must FAIL before the fix and PASS after.
//
// Each sub-call that might panic runs in its own goroutine so a panic in one
// does not leave meterMu locked (a mutex is NOT unlocked on panic, so panicking
// inside a locked critical section would deadlock every subsequent lock attempt).
func TestInterceptorsDoNotPanicWithoutSetupMeter(t *testing.T) {
	// Reset all global meter state to simulate a binary that never called SetupMeter.
	// Restore at cleanup so later tests in the package still see a valid registry.
	meterMu.Lock()
	savedGlobalReg := globalReg
	savedGlobalHandler := globalHandler
	savedSharedMetrics := sharedMetrics
	globalReg = nil
	globalHandler = nil
	sharedMetrics = nil
	meterMu.Unlock()

	fallbackMu.Lock()
	savedFallbackReg := fallbackReg
	fallbackReg = nil
	fallbackMu.Unlock()

	t.Cleanup(func() {
		meterMu.Lock()
		globalReg = savedGlobalReg
		globalHandler = savedGlobalHandler
		sharedMetrics = savedSharedMetrics
		meterMu.Unlock()

		fallbackMu.Lock()
		fallbackReg = savedFallbackReg
		fallbackMu.Unlock()
	})

	// Sub-test 1: constructing the gRPC unary interceptor must NOT panic.
	// Run in a goroutine so a panic (pre-fix) does not leave meterMu locked and
	// deadlock the rest of this test.
