	var buf bytes.Buffer
	l := NewLogger(&buf, slog.LevelInfo).With("component", "auth")

	ctx := WithRequestID(context.Background(), "req_xyz")
	l.InfoContext(ctx, "scoped log")

	out := buf.String()
	if !strings.Contains(out, `"component":"auth"`) {
		t.Errorf("expected component attr from With(), got %s", out)
	}
	if !strings.Contains(out, `"request_id":"req_xyz"`) {
		t.Errorf("ctx request_id should still be injected after With(), got %s", out)
	}
}

// TestLoggerWithGroup verifies slog's WithGroup() chain still injects
// context fields. Exercises ctxHandler.WithGroup.
func TestLoggerWithGroup(t *testing.T) {
	var buf bytes.Buffer
	l := NewLogger(&buf, slog.LevelInfo).WithGroup("svc")

	ctx := WithTenantID(context.Background(), "org_42")
	l.InfoContext(ctx, "grouped log", "key", "value")

	out := buf.String()
	if !strings.Contains(out, `"svc":{`) {
		t.Errorf("expected svc group prefix, got %s", out)
	}
	// Context fields are added by ctxHandler.Handle (not via WithAttrs),
