	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/exporters/otlp/otlptrace/otlptracegrpc"
	"go.opentelemetry.io/otel/sdk/resource"
	sdktrace "go.opentelemetry.io/otel/sdk/trace"
	semconv "go.opentelemetry.io/otel/semconv/v1.26.0"
	"go.opentelemetry.io/otel/trace"
	"google.golang.org/grpc"
)

const tracerName = "github.com/zenithflowinc/omnicore-platform"

// tracerConfig is the resolved set of tracer options after applying every
// TracerOption. Default is "TLS required" — operators must opt in to
// plaintext via WithOTLPInsecure. T1.6 from the 2026-05-05 foundation-
// readiness review.
type tracerConfig struct {
	insecure bool
}

// TracerOption tunes SetupTracer. Use WithOTLPInsecure for the dev-stack
// case where the OTLP collector runs on the same Docker network as the
// service and TLS is not configured.
type TracerOption func(*tracerConfig)

// WithOTLPInsecure opts the OTLP exporter into plaintext gRPC. Trace
// payloads carry request IDs, tenant IDs, and timing of every RPC; in any
// environment where the OTLP transport could be intercepted this is a
// PII / topology exfiltration vector. Use only when the path between
// service and collector is known to be private (single-host Docker
// network, in-cluster pod-to-pod with mTLS at the mesh layer, etc.).
func WithOTLPInsecure() TracerOption {
	return func(c *tracerConfig) { c.insecure = true }
}

// SetupTracer initializes the global OTel tracer provider that exports to
// the OTel Collector at otlpEndpoint over gRPC. Returns a shutdown function
// the caller MUST defer at service start.
//
// TLS is enforced by default (T1.6). Pass WithOTLPInsecure() to opt into
// plaintext — typically only the dev compose stack and CI runners.
func SetupTracer(ctx context.Context, serviceName, otlpEndpoint string, opts ...TracerOption) (func(context.Context) error, error) {
	if serviceName == "" {
		return nil, New(CodeValidationFailed, "serviceName required")
	}
	if otlpEndpoint == "" {
		return nil, New(CodeValidationFailed, "otlpEndpoint required")
	}

	cfg := tracerConfig{}
	for _, o := range opts {
		o(&cfg)
	}

	dialOpts := []otlptracegrpc.Option{
		otlptracegrpc.WithEndpoint(otlpEndpoint),
	}
	if cfg.insecure {
		dialOpts = append(dialOpts, otlptracegrpc.WithInsecure())
	}
	exp, err := otlptracegrpc.New(ctx, dialOpts...)
	if err != nil {
		return nil, Wrap(CodeServiceUnavailable, "otlptrace exporter", err)
	}

	res, err := resource.New(ctx,
		resource.WithAttributes(
			semconv.ServiceName(serviceName),
		),
	)
	if err != nil {
		return nil, Wrap(CodeInternal, "resource", err)
	}

	tp := sdktrace.NewTracerProvider(
		sdktrace.WithBatcher(exp),
		sdktrace.WithResource(res),
	)
	otel.SetTracerProvider(tp)

	return tp.Shutdown, nil
}

// Tracer returns the global named tracer. Safe to call before SetupTracer
// (returns a no-op tracer until SetupTracer runs).
func Tracer() trace.Tracer {
	return otel.Tracer(tracerName)
}

// GRPCServerOptions returns the grpc.ServerOption that installs otelgrpc's
// server stats handler (P0-10 / #2399: before this, no Go gRPC server in the
// platform produced a span per request or extracted an inbound traceparent,
// despite every service already calling SetupTracer). Pass it alongside a
// service's existing grpc.ServerOption slice, e.g.:
//
//	opts := []grpc.ServerOption{
//		grpc.ChainUnaryInterceptor(...),
//		observability.GRPCServerOptions(),
//	}
//	s := grpc.NewServer(opts...)
//
// The stats handler extracts a traceparent carried in inbound gRPC metadata
// (propagated by grpcclient.DialOptions' client stats handler, or by
// bffserver's otelhttp middleware when a BFF forwards trace context onto its
// backend calls) and starts a server span as its child, so a trace continues
// unbroken across the hop rather than starting a new, disconnected trace at
// each service boundary.
func GRPCServerOptions() grpc.ServerOption {
	return grpc.StatsHandler(otelgrpc.NewServerHandler())
}


