	if !errors.Is(e, cause) {
		t.Error("errors.Is(e, cause) should be true")
	}
	if e.Unwrap() != cause {
		t.Error("Unwrap should return cause")
	}
}

func TestWithRequestID(t *testing.T) {
	e := New(CodeForbidden, "missing scope")
	if e.RequestID != "" {
		t.Error("default RequestID should be empty")
	}
	e2 := e.WithRequestID("req_abc")
	if e2.RequestID != "req_abc" {
		t.Errorf("e2.RequestID = %q, want req_abc", e2.RequestID)
	}
	if e.RequestID != "" {
		t.Error("WithRequestID should return a copy; original modified")
	}
