package observability

import (
	"context"
	"sync"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
)

// fallbackMu guards fallbackReg.
var fallbackMu sync.Mutex

// fallbackReg is the lazily-created fallback Prometheus registry used when
// SetupMeter has not been called (tests, tooling). Nothing scrapes this
// registry in production — it exists so instruments can be registered without
// panicking. Exposed as a package-level var so white-box tests in this package
// can scrape it directly.
var fallbackReg *prometheus.Registry

// grpcMetricSet holds the three Prometheus instruments for gRPC server metrics.
// Registered lazily on first interceptor/middleware construction via
// initSharedMetrics. When SetupMeter has not been called the instruments are
// registered on the package-level fallbackReg instead — never panics.
//
// Label design (spec §hard requirements): a single unified label set
// {endpoint, status_class} is shared by both the gRPC interceptor and the
// HTTP middleware so there is exactly ONE registration of
// omnicore_requests_total per binary regardless of how many interceptors and
// middleware are wired. Spec §5 PromQL never filters on the endpoint label, so
// this is fully compatible. The label is named "endpoint" (neutral term that
// covers both gRPC FullMethod and HTTP route patterns).
type grpcMetricSet struct {
	requestsTotal   *prometheus.CounterVec
	requestDuration *prometheus.HistogramVec
	requestsInFlight prometheus.Gauge
}

// sharedMetrics is the one process-wide instrument set. It is initialised by
// initSharedMetrics the first time either interceptor or HTTP middleware
// constructor is called. Guarded by the global meterMu.
var sharedMetrics *grpcMetricSet

// initSharedMetrics registers the three instruments against globalReg, or
// against a lazily-created fallback registry when SetupMeter has not been
// called (tests, standalone tooling). Never panics.
//
// Production path: SetupMeter creates globalReg and resets sharedMetrics = nil
// (see meter.go), so the next interceptor/middleware construction re-registers
// against the served Prometheus registry. That scrape-visible behavior is
// unchanged.
//
// Fallback path: when globalReg == nil the instruments are registered on a
// package-level fallbackReg (created once, guarded by fallbackMu). Nothing
// scrapes fallbackReg in production — it exists so the interceptors/middleware
// can be constructed without a SetupMeter call (e.g. in gRPC server tests that
// wire the real interceptor chain but don't need metrics export).
//
// Must be called under meterMu.Lock().
func initSharedMetrics() {
	if sharedMetrics != nil {
		return // already initialised
	}

	// Determine which registry to register against.
	reg := globalReg
	if reg == nil {
		// SetupMeter was not called — use (or create) the fallback registry.
		// We must release meterMu before acquiring fallbackMu to preserve the
		// lock-order invariant (meterMu → fallbackMu). Releasing here is safe
		// because sharedMetrics is still nil; no other goroutine can sneak in
		// because they also need meterMu.
		//
		// Re-check sharedMetrics after re-acquiring meterMu to handle the
		// (unlikely) race where two goroutines both saw nil simultaneously.
		meterMu.Unlock()
		fallbackMu.Lock()
		if fallbackReg == nil {
			fallbackReg = prometheus.NewRegistry()
		}
		reg = fallbackReg
		fallbackMu.Unlock()
		meterMu.Lock()

		// Another goroutine may have initialised sharedMetrics while we
		// released meterMu.
		if sharedMetrics != nil {
			return
		}
		// globalReg may now have been set by a concurrent SetupMeter call;
		// prefer it over the fallback.
		if globalReg != nil {
			reg = globalReg
		}
	}

	requestsTotal := prometheus.NewCounterVec(prometheus.CounterOpts{
		Name: "omnicore_requests_total",
		Help: "Total requests by endpoint and outcome class.",
	}, []string{"endpoint", "status_class"})

	requestDuration := prometheus.NewHistogramVec(prometheus.HistogramOpts{
		Name:    "omnicore_request_duration_seconds",
		Help:    "Request latency in seconds by endpoint and outcome class.",
		Buckets: []float64{0.001, 0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5, 10},
	}, []string{"endpoint", "status_class"})

	requestsInFlight := prometheus.NewGauge(prometheus.GaugeOpts{
		Name: "omnicore_requests_in_flight",
		Help: "Number of requests currently being processed.",
	})

	reg.MustRegister(requestsTotal, requestDuration, requestsInFlight)
	sharedMetrics = &grpcMetricSet{
		requestsTotal:    requestsTotal,
		requestDuration:  requestDuration,
		requestsInFlight: requestsInFlight,
	}
}

// grpcStatusClass maps a gRPC status code to one of three string labels used
// in the PromQL queries in spec §5: "ok", "client_error", "server_error".
//
// Mapping rationale:
//   - ok:           OK
//   - client_error: InvalidArgument, NotFound, PermissionDenied,
//                   Unauthenticated, AlreadyExists, FailedPrecondition,
//                   ResourceExhausted, OutOfRange, Canceled
//   - server_error: Internal, Unknown, Unavailable, DataLoss,
//                   Unimplemented, DeadlineExceeded, Aborted
func grpcStatusClass(code codes.Code) string {
	switch code {
	case codes.OK:
		return "ok"
	case codes.InvalidArgument,
		codes.NotFound,
		codes.PermissionDenied,
		codes.Unauthenticated,
		codes.AlreadyExists,
		codes.FailedPrecondition,
		codes.ResourceExhausted,
		codes.OutOfRange,
		codes.Canceled:
		return "client_error"
	default:
		// Internal, Unknown, Unavailable, DataLoss, Unimplemented,
		// DeadlineExceeded, Aborted, and any future codes.
		return "server_error"
	}
}

// UnaryServerMetricsInterceptor returns a gRPC unary server interceptor that
// records omnicore_request_duration_seconds, omnicore_requests_total, and
// omnicore_requests_in_flight for every RPC.
//
// In-flight gauge is incremented on entry and decremented via defer, so a
// panicking handler still decrements (the interceptor catches the panic,
// decrements, then re-panics — no goroutine is leaked and no counter stuck).
func UnaryServerMetricsInterceptor() grpc.UnaryServerInterceptor {
	meterMu.Lock()
	initSharedMetrics()
	m := sharedMetrics
	meterMu.Unlock()

	return func(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (resp interface{}, err error) {
		endpoint := info.FullMethod
		start := time.Now()

		m.requestsInFlight.Inc()
		panicked := true
		defer func() {
			if panicked {
				// Handler panicked — dec in-flight and re-panic.
				m.requestsInFlight.Dec()
			}
		}()

		resp, err = handler(ctx, req)
		panicked = false
		m.requestsInFlight.Dec()

		sc := grpcStatusClass(status.Code(err))
		elapsed := time.Since(start).Seconds()
		m.requestsTotal.WithLabelValues(endpoint, sc).Inc()
		m.requestDuration.WithLabelValues(endpoint, sc).Observe(elapsed)

		return resp, err
	}
}

// StreamServerMetricsInterceptor returns a gRPC stream server interceptor that
// records the same three instruments as UnaryServerMetricsInterceptor.
// Duration covers the lifetime of the stream from open to close.
func StreamServerMetricsInterceptor() grpc.StreamServerInterceptor {
	meterMu.Lock()
	initSharedMetrics()
	m := sharedMetrics
	meterMu.Unlock()

	return func(srv interface{}, ss grpc.ServerStream, info *grpc.StreamServerInfo, handler grpc.StreamHandler) (err error) {
		endpoint := info.FullMethod
		start := time.Now()

		m.requestsInFlight.Inc()
		panicked := true
		defer func() {
			if panicked {
				m.requestsInFlight.Dec()
			}
		}()

		err = handler(srv, ss)
		panicked = false
		m.requestsInFlight.Dec()

		sc := grpcStatusClass(status.Code(err))
		elapsed := time.Since(start).Seconds()
		m.requestsTotal.WithLabelValues(endpoint, sc).Inc()
		m.requestDuration.WithLabelValues(endpoint, sc).Observe(elapsed)

		return err
	}
}


