// ── Step 1.2: gRPC server metrics interceptors ────────────────────────────────

// setupMeterForTest creates a fresh meter and returns it + a cleanup func.
// Each test that needs a fresh registry must call this to avoid cross-test
// pollution from the package-level global.
func setupMeterForTest(t *testing.T, svcName string) (cleanup func()) {
	t.Helper()
	shutdown, err := SetupMeter(context.Background(), svcName, "1.0.0-test")
	if err != nil {
		t.Fatalf("SetupMeter: %v", err)
	}
	return func() {
		ctx, cancel := context.WithTimeout(context.Background(), time.Second)
		defer cancel()
		_ = shutdown(ctx)
	}
}

// statusClassFromGRPCCode tests exercise the internal mapping logic via the
// public interceptors. We verify the /metrics output contains expected labels.

func TestUnaryServerMetrics_RecordsDurationAndStatusClass_OK(t *testing.T) {
	cleanup := setupMeterForTest(t, "grpc-ok-test")
	defer cleanup()

	interceptor := UnaryServerMetricsInterceptor()

	called := false
	handler := func(ctx context.Context, req interface{}) (interface{}, error) {
		called = true
		return "resp", nil
	}

	info := &grpc.UnaryServerInfo{FullMethod: "/omnicore.identity.user.v1.UserService/InviteUser"}
	resp, err := interceptor(context.Background(), "req", info, handler)

	if !called {
		t.Error("handler was not called")
