			}
		}()
		_, _ = interceptor(context.Background(), nil, info, panicHandler)
	}()

	// After the panic+recover, in-flight must be back to 0.
	// We verify this by scraping — the gauge should be 0 (or absent means 0).
	body := scrapeMetrics(t)
	// omnicore_requests_in_flight must be 0 — it was inc'd then dec'd.
	// Prometheus omits the line when the value is 0 for gauges that were
	// registered but returned to 0; we just need to confirm no crash.
	// A stricter check: if the line appears, it must not say "1".
	for _, line := range strings.Split(body, "\n") {
		if strings.HasPrefix(line, "omnicore_requests_in_flight") && !strings.HasPrefix(line, "#") {
			if strings.HasSuffix(strings.TrimSpace(line), " 1") {
				t.Errorf("in-flight gauge must be 0 after panic recovery; got: %q", line)
			}
		}
	}
}

