// ── Behavior: no-panic lazy init when SetupMeter was never called ─────────────

// TestInterceptorsDoNotPanicWithoutSetupMeter is the regression test for the
// CI-breaking bug where initSharedMetrics() panicked when globalReg == nil.
//
// Production always calls SetupMeter at boot. Tests that build the real gRPC
// server (e.g. mTLS + pact provider tests) do not call SetupMeter, which caused
// every such test to panic via UnaryServerMetricsInterceptor().
//
// The fix: lazy-init against a fallback Prometheus registry when globalReg is nil.
// This test must FAIL before the fix and PASS after.
//
// Each sub-call that might panic runs in its own goroutine so a panic in one
// does not leave meterMu locked (a mutex is NOT unlocked on panic, so panicking
// inside a locked critical section would deadlock every subsequent lock attempt).
func TestInterceptorsDoNotPanicWithoutSetupMeter(t *testing.T) {
	// Reset all global meter state to simulate a binary that never called SetupMeter.
	// Restore at cleanup so later tests in the package still see a valid registry.
	meterMu.Lock()
	savedGlobalReg := globalReg
	savedGlobalHandler := globalHandler
	savedSharedMetrics := sharedMetrics
	globalReg = nil
	globalHandler = nil
	sharedMetrics = nil
	meterMu.Unlock()

	fallbackMu.Lock()
	savedFallbackReg := fallbackReg
	fallbackReg = nil
	fallbackMu.Unlock()

	t.Cleanup(func() {
		meterMu.Lock()
		globalReg = savedGlobalReg
		globalHandler = savedGlobalHandler
		sharedMetrics = savedSharedMetrics
		meterMu.Unlock()

		fallbackMu.Lock()
		fallbackReg = savedFallbackReg
		fallbackMu.Unlock()
	})

	// Sub-test 1: constructing the gRPC unary interceptor must NOT panic.
	// Run in a goroutine so a panic (pre-fix) does not leave meterMu locked and
	// deadlock the rest of this test.
	type interceptorResult struct {
		interceptor grpc.UnaryServerInterceptor
		panicked    bool
		panicVal    interface{}
	}
	intrCh := make(chan interceptorResult, 1)
	go func() {
		r := interceptorResult{}
		defer func() {
			if p := recover(); p != nil {
				r.panicked = true
				r.panicVal = p
			}
			intrCh <- r
		}()
		r.interceptor = UnaryServerMetricsInterceptor()
	}()
	intrRes := <-intrCh
	if intrRes.panicked {
		t.Errorf("UnaryServerMetricsInterceptor() must not panic without SetupMeter — panicked: %v", intrRes.panicVal)
		return // mutex is unusable after panic; abandon remaining sub-tests
	}

	// Sub-test 2: constructing the HTTP middleware must NOT panic.
	mwCh := make(chan interface{}, 1) // nil = no panic, non-nil = panic value
	go func() {
		defer func() {
			mwCh <- recover()
		}()
		HTTPMetricsMiddleware()
		mwCh <- nil
	}()
	if p := <-mwCh; p != nil {
		t.Errorf("HTTPMetricsMiddleware() must not panic without SetupMeter — panicked: %v", p)
	}

	// Sub-test 3: invoking the interceptor must NOT panic and must record metrics.
	type invokeResult struct {
		panicked bool
		panicVal interface{}
	}
	invCh := make(chan invokeResult, 1)
	go func() {
		r := invokeResult{}
		defer func() {
			if p := recover(); p != nil {
				r.panicked = true
				r.panicVal = p
			}
			invCh <- r
		}()
		handler := func(ctx context.Context, req interface{}) (interface{}, error) {
			return "ok", nil
		}
		info := &grpc.UnaryServerInfo{FullMethod: "/test.v1.Svc/NoSetupMeterMethod"}
		_, _ = intrRes.interceptor(context.Background(), nil, info, handler)
	}()
	invRes := <-invCh
	if invRes.panicked {
		t.Errorf("invoking interceptor must not panic without SetupMeter — panicked: %v", invRes.panicVal)
	}

	// Sub-test 4: fallback registry must contain omnicore_requests_total.
	fallbackMu.Lock()
	reg := fallbackReg
	fallbackMu.Unlock()

	if reg == nil {
		t.Fatal("fallbackReg must be non-nil after interceptor construction without SetupMeter")
	}

	req := httptest.NewRequest(http.MethodGet, "/metrics", nil)
	rr := httptest.NewRecorder()
	promhttp.HandlerFor(reg, promhttp.HandlerOpts{}).ServeHTTP(rr, req)
	body, _ := io.ReadAll(rr.Body)
	bodyStr := string(body)

	if !strings.Contains(bodyStr, "omnicore_requests_total") {
		t.Errorf("fallback registry must record omnicore_requests_total; got:\n%s", bodyStr)
	}
	if !strings.Contains(bodyStr, `status_class="ok"`) {
		t.Errorf("fallback registry must contain status_class=ok; got:\n%s", bodyStr)
	}
}

