// scrapeMetrics reads the current /metrics output from the global handler.
func scrapeMetrics(t *testing.T) string {
	t.Helper()
	h := MetricsHandler()
	if h == nil {
		t.Fatal("MetricsHandler() returned nil — was SetupMeter called?")
	}
	req := httptest.NewRequest(http.MethodGet, "/metrics", nil)
	rr := httptest.NewRecorder()
	h.ServeHTTP(rr, req)
	body, _ := io.ReadAll(rr.Body)
	return string(body)
}

