package observability

import (
	"bufio"
	"fmt"
	"net"
	"net/http"
	"time"

	chi "github.com/go-chi/chi/v5"
)

// Compile-time assertions: responseWriter must satisfy http.Hijacker and
// http.Flusher so that WebSocket upgrades and SSE flushes work through the
// middleware without a type-assertion failure.
var (
	_ http.Hijacker = (*responseWriter)(nil)
	_ http.Flusher  = (*responseWriter)(nil)
)

// responseWriter wraps http.ResponseWriter to capture the status code.
// It also delegates http.Hijacker (for WebSocket upgrades) and http.Flusher
// (for SSE / streaming responses) to the underlying writer when supported.
type responseWriter struct {
	http.ResponseWriter
	statusCode int
	written    bool
	// hijacked is set to true when Hijack() is called. When true the middleware
	// skips recording omnicore_requests_total and omnicore_request_duration_seconds
	// because a hijacked connection is a long-lived protocol upgrade, not a
	// regular HTTP request, and recording its lifetime inflates p95 latency and
	// falsely classifies the upgrade as a 5xx error.
	hijacked bool
}

func wrapResponseWriter(w http.ResponseWriter) *responseWriter {
	return &responseWriter{ResponseWriter: w, statusCode: http.StatusOK}
}

func (rw *responseWriter) WriteHeader(code int) {
	if !rw.written {
		rw.statusCode = code
		rw.written = true
		rw.ResponseWriter.WriteHeader(code)
	}
}

// NOTE: responseWriter deliberately does NOT override Write. The embedded
// http.ResponseWriter's Write is promoted and used as-is, so the request body
// passes straight through to the underlying writer untouched. Overriding Write
// to delegate `rw.ResponseWriter.Write(b)` made this wrapper a CodeQL
// reflected-XSS sink (go/reflected-xss) even though it introduces no data —
// status capture only needs WriteHeader, so the override was unnecessary.

// Hijack implements http.Hijacker by delegating to the underlying
// ResponseWriter. Returns an error if the underlying writer does not support
// hijacking (e.g. httptest.NewRecorder). On success, sets rw.hijacked = true
// so the metrics middleware skips request counting for this connection.
func (rw *responseWriter) Hijack() (net.Conn, *bufio.ReadWriter, error) {
	hj, ok := rw.ResponseWriter.(http.Hijacker)
	if !ok {
		return nil, nil, fmt.Errorf("observability: underlying ResponseWriter does not implement http.Hijacker")
	}
	rw.hijacked = true
	return hj.Hijack()
}

// Flush implements http.Flusher by delegating to the underlying
// ResponseWriter. It is a no-op when the underlying writer does not support
// flushing — callers that depend on incremental delivery should use a server
// that provides a flush-capable ResponseWriter (e.g. httptest.NewServer).
func (rw *responseWriter) Flush() {
	if f, ok := rw.ResponseWriter.(http.Flusher); ok {
		f.Flush()
	}
}

// Sentinel route labels. Neither is ever derived from request input — both
// are fixed strings — so no unauthenticated caller can mint an unbounded
// number of distinct label sets (F21 / issue #1827).
const (
	// unmatchedRouteLabel is used when a chi RouteContext exists but no route
	// matched (the attacker-reachable case: a 404 against an arbitrary path,
	// reachable pre-auth on any service that mounts this middleware at the
	// root router, e.g. shell-bff).
	unmatchedRouteLabel = "unmatched"
	// noChiContextLabel is used when there is no chi RouteContext at all —
	// e.g. a plain http.Handler wrapper in a test harness that never went
	// through a chi router. Kept distinct from unmatchedRouteLabel because
	// it indicates a wiring shape, not an attacker-controlled 404.
	noChiContextLabel = "unknown"
)

// metricsRouteLabel derives the bounded-cardinality route label for a
// request: chi's matched RoutePattern when a route matched, otherwise one of
// the two fixed sentinels above. The raw r.URL.Path must never be used here
// — it is attacker-controlled input and using it as a label value lets an
// unauthenticated caller OOM the process by requesting distinct nonexistent
// paths (F21 / issue #1827).
func metricsRouteLabel(r *http.Request) string {
	rctx := chi.RouteContext(r.Context())
	if rctx == nil {
		return noChiContextLabel
	}
	if pattern := rctx.RoutePattern(); pattern != "" {
		return pattern
	}
	return unmatchedRouteLabel
}

// httpStatusClass maps an HTTP status code to the 3-value enum used in PromQL:
// "2xx", "3xx", "4xx", or "5xx". Codes outside the standard ranges default to
// "5xx" (treated as server-side anomalies).
func httpStatusClass(code int) string {
	switch {
	case code >= 200 && code < 300:
		return "2xx"
	case code >= 300 && code < 400:
		return "3xx"
	case code >= 400 && code < 500:
		return "4xx"
	default:
		return "5xx"
	}
}

// HTTPMetricsMiddleware returns a chi-compatible http.Handler middleware that
// records omnicore_request_duration_seconds, omnicore_requests_total, and
// omnicore_requests_in_flight for every HTTP request.
//
// Route label: uses chi's RoutePattern (the matched pattern, e.g.
// "/api/v1/items/{id}") to keep label cardinality bounded. Never uses the raw
// URL path: see metricsRouteLabel for the fixed sentinels used instead when
// no route matched or no chi context is present.
//
// Shared instruments: reuses the same three Prometheus instruments as
// UnaryServerMetricsInterceptor — see spec §hard requirements note in
// grpc_metrics.go. Both gRPC and HTTP use {endpoint, status_class} labels so
// there is exactly ONE registration of omnicore_requests_total per binary.
//
// In-flight gauge is incremented on entry and decremented via defer so a
// panicking handler still decrements (the middleware catches the panic,
// decrements, then re-panics — no goroutine is leaked and no counter stuck).
func HTTPMetricsMiddleware() func(http.Handler) http.Handler {
	meterMu.Lock()
	initSharedMetrics()
	m := sharedMetrics
	meterMu.Unlock()

	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			start := time.Now()
			wrapped := wrapResponseWriter(w)

			m.requestsInFlight.Inc()
			panicked := true
			defer func() {
				if panicked {
					m.requestsInFlight.Dec()
				}
			}()

			next.ServeHTTP(wrapped, r)
			panicked = false
			m.requestsInFlight.Dec()

			// Hijacked connections (WebSocket upgrades) are long-lived protocol
			// switches, not regular HTTP requests. Recording them would:
			//   • inflate p95 request latency (connection lifetime ≠ request latency)
			//   • falsely count the upgrade as a 5xx (the go net/http server
			//     returns 200 when the conn is hijacked, but WS upgrade code is 101)
			// Skip both counters; the in-flight gauge already balanced above.
			if wrapped.hijacked {
				return
			}

			// Derive the route label from chi's RoutePattern (e.g.
			// "/api/v1/items/{id}") so path parameters don't explode
			// cardinality, falling back to a fixed sentinel — never the raw
			// path — when no route matched or no chi context is present.
			// See metricsRouteLabel for why the raw path is never used.
			endpoint := metricsRouteLabel(r)
			// Append method so /GET /api/v1/users and /POST /api/v1/users are
			// distinct label values — matches gRPC FullMethod format practice.
			endpoint = r.Method + " " + endpoint

			sc := httpStatusClass(wrapped.statusCode)
			elapsed := time.Since(start).Seconds()
			m.requestsTotal.WithLabelValues(endpoint, sc).Inc()
			m.requestDuration.WithLabelValues(endpoint, sc).Observe(elapsed)
		})
	}
}


