		t.Errorf("expected chi route pattern /api/v1/items/{id} in /metrics; got:\n%s", body)
	}
}

func TestHTTPMetrics_InFlightOnPanic(t *testing.T) {
	cleanup := setupMeterForTest(t, "http-panic-test")
	defer cleanup()

	r := chi.NewRouter()
	r.Use(HTTPMetricsMiddleware())
	r.Get("/boom", func(w http.ResponseWriter, r *http.Request) {
		panic("http panic")
	})

	req := httptest.NewRequest(http.MethodGet, "/boom", nil)
	rr := httptest.NewRecorder()

	// The middleware must dec in-flight on panic; the panic propagates up.
	func() {
		defer func() {
			r := recover()
			if r == nil {
				t.Error("expected middleware to re-panic")
			}
		}()
		r.ServeHTTP(rr, req)
	}()

	body := scrapeMetrics(t)
	for _, line := range strings.Split(body, "\n") {
		if strings.HasPrefix(line, "omnicore_requests_in_flight") && !strings.HasPrefix(line, "#") {
			if strings.HasSuffix(strings.TrimSpace(line), " 1") {
				t.Errorf("in-flight must be 0 after HTTP panic recovery; got: %q", line)
			}
		}
	}
}

func TestHTTPMetrics_InFlightIncrementsAndDecrements(t *testing.T) {
	cleanup := setupMeterForTest(t, "http-inflight-test")
	defer cleanup()

	// Channel to signal the handler to proceed — lets us observe in-flight > 0.
	proceed := make(chan struct{})
	done := make(chan struct{})

	r := chi.NewRouter()
	r.Use(HTTPMetricsMiddleware())
	r.Get("/slow", func(w http.ResponseWriter, req *http.Request) {
		close(proceed)
		<-done
		w.WriteHeader(http.StatusOK)
	})

	// Start the request in a goroutine.
	go func() {
		req := httptest.NewRequest(http.MethodGet, "/slow", nil)
		rr := httptest.NewRecorder()
		r.ServeHTTP(rr, req)
	}()

	// Wait until the handler is blocked.
	select {
	case <-proceed:
	case <-time.After(2 * time.Second):
		t.Fatal("handler never signalled ready")
	}

	// Let the handler finish.
	close(done)
}

// TestHTTPMetrics_NoChiContextUsesUnknownSentinel covers the case where the
// middleware wraps a plain http.Handler with no chi RouteContext at all (e.g.
// a non-chi test harness or wrapper). No raw path may ever reach a label
// value, so this collapses to the fixed "unknown" sentinel — distinct from
// the "unmatched" sentinel used when a chi RouteContext exists but no route
