// ── Behavior: Hijacker passthrough ───────────────────────────────────────────

// TestHTTPMetrics_HijackerPassthrough asserts that a handler sitting behind
// HTTPMetricsMiddleware can successfully perform a WebSocket-style hijack.
// httptest.NewServer is used because its ResponseWriter implements http.Hijacker;
// httptest.NewRecorder does NOT.
func TestHTTPMetrics_HijackerPassthrough(t *testing.T) {
	cleanup := setupMeterForTest(t, "http-hijack-test")
	defer cleanup()

	hijackDone := make(chan error, 1)

	handler := HTTPMetricsMiddleware()(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		hj, ok := w.(http.Hijacker)
		if !ok {
			hijackDone <- fmt.Errorf("http.Hijacker assertion failed — wrapper does not implement http.Hijacker")
			return
		}
		conn, bufrw, err := hj.Hijack()
		if err != nil {
			hijackDone <- fmt.Errorf("Hijack() returned error: %w", err)
			return
		}
		// Write a raw HTTP response and close.
		_, _ = fmt.Fprintf(bufrw, "HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\n\r\n")
		_ = bufrw.Flush()
		_ = conn.Close()
		hijackDone <- nil
	}))

	srv := httptest.NewServer(handler)
	defer srv.Close()

	// Connect and send a plain HTTP request — the handler hijacks the conn.
	conn, err := net.Dial("tcp", srv.Listener.Addr().String())
	if err != nil {
		t.Fatalf("dial failed: %v", err)
	}
	defer conn.Close()

	_, _ = fmt.Fprintf(conn, "GET /ws HTTP/1.1\r\nHost: localhost\r\nUpgrade: websocket\r\n\r\n")

	select {
	case err := <-hijackDone:
		if err != nil {
			t.Errorf("Hijacker passthrough failed: %v", err)
		}
	case <-time.After(3 * time.Second):
		t.Fatal("handler never signalled hijack result")
	}

	// Read the raw response to confirm the server wrote our 101.
	buf := make([]byte, 256)
	_ = conn.SetReadDeadline(time.Now().Add(time.Second))
	n, _ := conn.Read(buf)
	got := string(buf[:n])
	if !strings.Contains(got, "101 Switching Protocols") {
		t.Errorf("expected 101 Switching Protocols in raw response; got: %q", got)
	}
}

// ── Behavior: Flusher passthrough ────────────────────────────────────────────

// TestHTTPMetrics_FlusherPassthrough asserts that a handler behind the
// middleware can successfully obtain http.Flusher from the wrapped writer and
// call Flush() without error. Uses httptest.NewServer whose ResponseWriter
// implements http.Flusher.
func TestHTTPMetrics_FlusherPassthrough(t *testing.T) {
	cleanup := setupMeterForTest(t, "http-flusher-test")
	defer cleanup()

	flusherOK := make(chan bool, 1)
	flushCalled := make(chan struct{})

	handler := HTTPMetricsMiddleware()(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		f, ok := w.(http.Flusher)
		flusherOK <- ok
		if ok {
			// Write headers + body chunk, then flush.
			w.WriteHeader(http.StatusOK)
			_, _ = w.(io.Writer).Write([]byte("chunk"))
			f.Flush()
			close(flushCalled)
		}
	}))

	srv := httptest.NewServer(handler)
	defer srv.Close()

	resp, err := srv.Client().Get(srv.URL + "/stream")
	if err != nil {
		t.Fatalf("GET failed: %v", err)
	}
	defer resp.Body.Close()
	_, _ = io.ReadAll(resp.Body)

	select {
	case ok := <-flusherOK:
		if !ok {
			t.Error("http.Flusher assertion failed — wrapper does not implement http.Flusher")
		}
	case <-time.After(3 * time.Second):
		t.Fatal("handler never reported Flusher result")
	}
}

// ── Behavior: hijacked connections are NOT counted in request metrics ─────────

// TestHTTPMetrics_HijackedConnectionNotCounted asserts that when a handler
// hijacks the connection (WebSocket upgrade path), omnicore_requests_total is
// NOT incremented for that request — a hijacked connection is a long-lived
// upgrade, not a regular HTTP request, and recording its status as "5xx" would
// falsely inflate error rates.
func TestHTTPMetrics_HijackedConnectionNotCounted(t *testing.T) {
	cleanup := setupMeterForTest(t, "http-hijack-nocnt-test")
	defer cleanup()

	// Record the request total BEFORE the hijacking request fires.
	beforeBody := scrapeMetrics(t)
	countBefore := countMetricLines(beforeBody, "omnicore_requests_total", `endpoint="GET /ws"`)

	hijackDone := make(chan struct{})

	handler := HTTPMetricsMiddleware()(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		hj, ok := w.(http.Hijacker)
		if !ok {
			// If Hijacker not available, signal done to avoid test hang; the
			// HijackerPassthrough test will catch this failure.
			close(hijackDone)
			return
		}
		conn, bufrw, err := hj.Hijack()
		if err != nil {
			close(hijackDone)
			return
		}
		_, _ = fmt.Fprintf(bufrw, "HTTP/1.1 101 Switching Protocols\r\n\r\n")
		_ = bufrw.Flush()
		_ = conn.Close()
		close(hijackDone)
	}))

	srv := httptest.NewServer(handler)
	defer srv.Close()

	conn, err := net.Dial("tcp", srv.Listener.Addr().String())
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	defer conn.Close()
	_, _ = fmt.Fprintf(conn, "GET /ws HTTP/1.1\r\nHost: localhost\r\n\r\n")

	select {
	case <-hijackDone:
	case <-time.After(3 * time.Second):
		t.Fatal("hijack handler timed out")
	}

	// Drain connection so the server fully completes.
	_ = conn.SetReadDeadline(time.Now().Add(200 * time.Millisecond))
	_, _ = io.ReadAll(conn)

	afterBody := scrapeMetrics(t)
	countAfter := countMetricLines(afterBody, "omnicore_requests_total", `endpoint="GET /ws"`)

	if countAfter > countBefore {
		t.Errorf("omnicore_requests_total incremented for hijacked (WebSocket) connection: before=%d after=%d; hijacked requests must NOT be counted", countBefore, countAfter)
	}
}

// countMetricLines counts the number of non-comment lines in a Prometheus text
// body that start with metricName and contain the label substring.
func countMetricLines(body, metricName, labelSubstr string) int {
	count := 0
	for _, line := range strings.Split(body, "\n") {
		if strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, metricName) && strings.Contains(line, labelSubstr) {
			count++
		}
	}
	return count
}

// hijackableRecorder is a minimal http.ResponseWriter + http.Hijacker
// that records status and delegates hijacking to an in-memory net.Conn pair.
// Used only in unit tests where httptest.NewServer is not appropriate.
type hijackableRecorder struct {
	*httptest.ResponseRecorder
}

func (hr *hijackableRecorder) Hijack() (net.Conn, *bufio.ReadWriter, error) {
	client, server := net.Pipe()
	br := bufio.NewReadWriter(bufio.NewReader(server), bufio.NewWriter(server))
	// Close client end after yield — the test only checks delegation, not I/O.
	go func() { _ = client.Close() }()
	return server, br, nil
}



