package observability

import (
	"context"
	"io"
	"log/slog"
	"os"
)

type ctxKey string

const (
	ctxKeyRequestID ctxKey = "x-request-id"
	ctxKeyTraceID   ctxKey = "x-trace-id"
	ctxKeyTenantID  ctxKey = "x-tenant-id"
	ctxKeyUserID    ctxKey = "x-user-id"
	ctxKeyActorType ctxKey = "x-actor-type"
)

// WithRequestID returns ctx with x-request-id attached.
func WithRequestID(ctx context.Context, v string) context.Context {
	return context.WithValue(ctx, ctxKeyRequestID, v)
}

// WithTraceID returns ctx with x-trace-id attached.
func WithTraceID(ctx context.Context, v string) context.Context {
	return context.WithValue(ctx, ctxKeyTraceID, v)
}

// WithTenantID returns ctx with x-tenant-id attached.
func WithTenantID(ctx context.Context, v string) context.Context {
	return context.WithValue(ctx, ctxKeyTenantID, v)
}

// WithUserID returns ctx with x-user-id attached.
func WithUserID(ctx context.Context, v string) context.Context {
	return context.WithValue(ctx, ctxKeyUserID, v)
}

// WithActorType returns ctx with x-actor-type attached.
func WithActorType(ctx context.Context, v string) context.Context {
	return context.WithValue(ctx, ctxKeyActorType, v)
}

func fieldsFromCtx(ctx context.Context) []slog.Attr {
	var attrs []slog.Attr
	if v, ok := ctx.Value(ctxKeyRequestID).(string); ok && v != "" {
		attrs = append(attrs, slog.String("request_id", v))
	}
	if v, ok := ctx.Value(ctxKeyTraceID).(string); ok && v != "" {
		attrs = append(attrs, slog.String("trace_id", v))
	}
	if v, ok := ctx.Value(ctxKeyTenantID).(string); ok && v != "" {
		attrs = append(attrs, slog.String("tenant_id", v))
	}
	if v, ok := ctx.Value(ctxKeyUserID).(string); ok && v != "" {
		attrs = append(attrs, slog.String("user_id", v))
	}
	if v, ok := ctx.Value(ctxKeyActorType).(string); ok && v != "" {
		attrs = append(attrs, slog.String("actor_type", v))
	}
	return attrs
}

type ctxHandler struct {
	inner slog.Handler
}

func (h *ctxHandler) Enabled(ctx context.Context, level slog.Level) bool {
	return h.inner.Enabled(ctx, level)
}

func (h *ctxHandler) Handle(ctx context.Context, r slog.Record) error {
	for _, a := range fieldsFromCtx(ctx) {
		r.AddAttrs(a)
	}
	return h.inner.Handle(ctx, r)
}

func (h *ctxHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
	return &ctxHandler{inner: h.inner.WithAttrs(attrs)}
}

func (h *ctxHandler) WithGroup(name string) slog.Handler {
	return &ctxHandler{inner: h.inner.WithGroup(name)}
}

// NewLogger returns a slog.Logger that emits JSON to w at the given level
// and automatically includes x-request-id, x-trace-id, x-tenant-id,
// x-user-id, and x-actor-type from context on every log line.
func NewLogger(w io.Writer, level slog.Level) *slog.Logger {
	if w == nil {
		w = os.Stdout
	}
	base := slog.NewJSONHandler(w, &slog.HandlerOptions{Level: level})
	return slog.New(&ctxHandler{inner: base})
}


