package observability

import (
	"context"
	"net/http"
	"sync"

	prometheusexporter "go.opentelemetry.io/otel/exporters/prometheus"
	"go.opentelemetry.io/otel/sdk/metric"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/collectors"
	promhttp "github.com/prometheus/client_golang/prometheus/promhttp"
)

// meterState holds the process-wide Prometheus registry and HTTP handler.
// There is exactly one per binary — wired once by SetupMeter, read by
// MetricsHandler and the interceptors/middleware. This is the justified
// Singleton case for global metric providers (otel-instrumentation skill §Singleton).
var (
	meterMu      sync.Mutex
	globalReg    *prometheus.Registry
	globalHandler http.Handler
)

// SetupMeter initialises the process-wide Prometheus metric registry,
// registers the generic omnicore instruments, and emits a service_up gauge
// (constant 1, labeled with version). It mirrors SetupTracer's shape:
// returns a shutdown/flush func the caller MUST defer.
//
// serviceName is required; version may be empty (treated as "unknown").
// WithOTLPInsecure parity note: the meter side uses direct Prometheus scrape
// (Path B, spec §3), so there is no OTLP exporter dial option here.
func SetupMeter(ctx context.Context, serviceName, version string, _ ...MeterOption) (func(context.Context) error, error) {
	if serviceName == "" {
		return nil, New(CodeValidationFailed, "serviceName required")
	}
	if version == "" {
		version = "unknown"
	}

	reg := prometheus.NewRegistry()

	// Standard Go runtime + process collectors — same set files-svc uses.
	reg.MustRegister(collectors.NewGoCollector())
	reg.MustRegister(collectors.NewProcessCollector(collectors.ProcessCollectorOpts{}))

	// OTel Prometheus exporter bridges OTel instruments into the registry.
	promExp, err := prometheusexporter.New(
		prometheusexporter.WithRegisterer(reg),
		// Do NOT namespace — instrument names are already fully qualified
		// (omnicore_request_duration_seconds etc.) per spec §3.
		prometheusexporter.WithoutScopeInfo(),
		prometheusexporter.WithoutTargetInfo(),
	)
	if err != nil {
		return nil, Wrap(CodeInternal, "prometheus exporter", err)
	}

	// MeterProvider backed by the Prometheus exporter.
	mp := metric.NewMeterProvider(metric.WithReader(promExp))

	// service_up gauge — constant 1, carrying the version label as
	// build-info / liveness self-report (spec §3).
	// Registered directly on the Prometheus registry for exact name control
	// (no OTel name mangling).
	serviceUpGauge := prometheus.NewGaugeVec(prometheus.GaugeOpts{
		Name: "service_up",
		Help: "Always 1 while the service is running; version label carries the build version.",
	}, []string{"version"})
	reg.MustRegister(serviceUpGauge)
	serviceUpGauge.WithLabelValues(version).Set(1)

	handler := promhttp.HandlerFor(reg, promhttp.HandlerOpts{
		Registry: reg,
	})

	// Publish process-wide state so the interceptors and middleware can
	// instrument against the same MeterProvider. Reset sharedMetrics so
	// that the interceptors/middleware re-register against the new registry
	// (important in tests where SetupMeter is called multiple times).
	meterMu.Lock()
	globalReg = reg
	globalHandler = handler
	sharedMetrics = nil // force re-registration on next interceptor/middleware construction
	setGlobalMeterProvider(mp)
	meterMu.Unlock()

	shutdown := func(ctx context.Context) error {
		return mp.Shutdown(ctx)
	}
	return shutdown, nil
}

// MetricsHandler returns an http.Handler that serves the Prometheus text
// format at /metrics. It must be called after SetupMeter.
func MetricsHandler() http.Handler {
	meterMu.Lock()
	defer meterMu.Unlock()
	return globalHandler
}

// MeterOption is reserved for future tuning (mirrors TracerOption shape).
type MeterOption func()

// setGlobalMeterProvider stores mp in a package-level variable so future
// callers can obtain an otel.Meter for service-specific instruments without
// importing the OTel SDK directly (otel-instrumentation skill §Facade).
var (
	globalMPMu sync.RWMutex
	_globalMP  *metric.MeterProvider
)

func setGlobalMeterProvider(mp *metric.MeterProvider) {
	globalMPMu.Lock()
	defer globalMPMu.Unlock()
	_globalMP = mp
}

// GlobalMeterProvider returns the process-wide OTel MeterProvider initialised
// by SetupMeter. Returns nil if SetupMeter has not been called yet.
// Services that need custom instruments (beyond the generic request set) call
// GlobalMeterProvider().Meter("svc-name") and register their instruments there.
func GlobalMeterProvider() *metric.MeterProvider {
	globalMPMu.RLock()
	defer globalMPMu.RUnlock()
	return _globalMP
}


