	shutdown, err := SetupMeter(context.Background(), "flush-test-svc", "0.0.1")
	if err != nil {
		t.Fatalf("SetupMeter: %v", err)
	}

	done := make(chan error, 1)
	go func() {
		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
		defer cancel()
		done <- shutdown(ctx)
	}()

	select {
	case err := <-done:
		if err != nil {
			t.Errorf("shutdown returned err: %v", err)
		}
	case <-time.After(3 * time.Second):
		t.Fatal("shutdown did not return within 3s — possible deadlock or hang")
	}
